257	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
258	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
259	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
260	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
261	  const char* iceman = std::getenv("ICEMAN");
262	  if (!iceman || !*iceman) {
263	    std::fprintf(stderr,
264	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
265	                 "(export ICEMAN=<path to ICEman binary>)\n");
266	    return 2;
267	  }
268	  // Build vsim argv from the standalone template, appending user passthrough
269	  // and the JTAG port flag.
270	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
271	  if (elf.empty()) return 2;
272	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
273	  std::vector<std::string> vsim_pass = cli.passthrough;
274	  vsim_pass.push_back("--jtag-port");
275	  vsim_pass.push_back(jtag_port);
276	  std::string err;
277	  const std::vector<std::string> vsim_argv =
278	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
279	  if (!err.empty()) {
280	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
281	    return 2;
282	  }
283	  std::fprintf(stderr,
284	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
285	               jtag_port.c_str());
286	  if (fork_background(vsim_argv) < 0) {
287	    std::fprintf(stderr,
288	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
289	    return 1;
290	  }
291	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
292	  // Wait for the port to be LISTENing before launching the debugger (it does not
293	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
294	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
295	  // but launch anyway if it never appears.
296	  if (const int pnum = std::atoi(jtag_port.c_str());
297	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
298	    std::fprintf(stderr,
299	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
300	                 "after 20s; launching the debugger anyway\n",
301	                 jtag_port.c_str());
302	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
303	  // localhost, port 9104) instead of its default real-hardware adapter; without
304	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
305	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
306	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
307	}
